//! Audio analyses and scene detection of media generated by real ffmpeg.

use se_app::ports::{MediaJobOutput, MediaJobRunner, MediaTask};
use se_domain::{AnalysisResult, Flicks, SceneDetection, SilenceSettings};

use crate::support::{Progress, generate, probe, runner, spec, tools};

#[tokio::test]
async fn a_voice_like_file_gets_its_loudness_and_its_silence() {
    let Some(tools) = tools() else { return };
    let dir = tempfile::tempdir().unwrap();
    // 2 s of tone, 1 s of silence, 2 s of tone, in stereo.
    let input = generate(
        &tools,
        dir.path(),
        "voice.wav",
        &[
            "-f",
            "lavfi",
            "-i",
            "sine=frequency=1000:sample_rate=48000:duration=5",
            "-af",
            "volume=-11dB,volume=enable='between(t,2,3)':volume=0",
            "-ac",
            "2",
            "-c:a",
            "pcm_s16le",
        ],
    )
    .await;
    let probed = probe(&tools, &input).await;
    let task = MediaTask::AudioAnalysis {
        silence: SilenceSettings::SPEECH,
    };
    let progress = Progress::default();
    let output = runner(&tools)
        .run(&spec(task, &input, dir.path(), &probed), &progress)
        .await
        .unwrap();
    let MediaJobOutput::Analysis(AnalysisResult::AudioAnalysis(analysis)) = output else {
        panic!("an audio analysis was expected, got {output:?}");
    };
    assert_eq!(progress.last(), Some(1.0));
    assert_eq!(analysis.silences.len(), 1, "{:?}", analysis.silences);
    let silence = analysis.silences[0];
    let near = |time: Flicks, millis: u32| {
        (time.to_seconds_f64() - f64::from(millis) / 1000.0).abs() < 0.03
    };
    assert!(
        near(silence.start(), 2_000) && near(silence.end(), 3_000),
        "{silence:?}"
    );
    // ffmpeg's sine source peaks at 1/8 of full scale (−18 dBFS), −11 dB more is −29 dBFS, and
    // the mono → stereo upmix puts it at −3 dB in each channel: about −32 LUFS.
    let lufs = analysis.integrated_lufs.unwrap();
    assert!((-33.5..=-31.0).contains(&lufs), "{lufs}");
    assert_eq!(analysis.short_term.values.len(), 10);
}

#[tokio::test]
async fn cuts_between_shots_are_detected() {
    let Some(tools) = tools() else { return };
    let dir = tempfile::tempdir().unwrap();
    let input = generate(
        &tools,
        dir.path(),
        "shots.mp4",
        &[
            "-f",
            "lavfi",
            "-i",
            "color=c=red:s=640x360:r=25:d=2",
            "-f",
            "lavfi",
            "-i",
            "color=c=blue:s=640x360:r=25:d=2",
            "-f",
            "lavfi",
            "-i",
            "testsrc2=s=640x360:r=25:d=2",
            "-filter_complex",
            "[0:v][1:v][2:v]concat=n=3:v=1:a=0[v]",
            "-map",
            "[v]",
            "-c:v",
            "libx264",
            "-pix_fmt",
            "yuv420p",
        ],
    )
    .await;
    let probed = probe(&tools, &input).await;
    let task = MediaTask::SceneDetection {
        threshold: SceneDetection::DEFAULT_THRESHOLD,
    };
    let output = runner(&tools)
        .run(
            &spec(task, &input, dir.path(), &probed),
            &Progress::default(),
        )
        .await
        .unwrap();
    let MediaJobOutput::Analysis(AnalysisResult::SceneDetection(detection)) = output else {
        panic!("a scene detection was expected, got {output:?}");
    };
    assert_eq!(
        detection.changes,
        [Flicks::from_millis(2_000), Flicks::from_millis(4_000)]
    );
}

#[tokio::test]
async fn speech_audio_is_mono_16_khz_pcm_of_the_first_sound_stream() {
    use se_app::ports::SpeechAudioExtractor;

    let Some(tools) = tools() else { return };
    let dir = tempfile::tempdir().unwrap();
    let input = generate(
        &tools,
        dir.path(),
        "interview.mp4",
        &[
            "-f",
            "lavfi",
            "-i",
            "testsrc2=size=320x240:rate=25:duration=2",
            "-f",
            "lavfi",
            "-i",
            "sine=frequency=440:sample_rate=48000:duration=2",
            "-ac",
            "2",
            "-c:v",
            "libx264",
            "-c:a",
            "aac",
        ],
    )
    .await;
    let output = dir.path().join("transcription").join("speech-16k.wav");
    let progress = Progress::default();
    runner(&tools)
        .extract_speech_audio(&input, &output, &progress)
        .await
        .unwrap();
    assert_eq!(progress.last(), Some(1.0));
    let probed = probe(&tools, &output).await;
    let audio = &probed.info.audio_streams[0];
    assert_eq!(
        (audio.codec.as_str(), audio.channels, audio.sample_rate),
        ("pcm_s16le", 1, 16_000)
    );
    assert!(probed.info.video_stream.is_none());
    let leftovers: Vec<_> = std::fs::read_dir(output.parent().unwrap())
        .unwrap()
        .collect();
    assert_eq!(leftovers.len(), 1, "no .part file left");
}
